// Generated by Gecko from a screen recording. Fails while the bug exists.
import { test, expect } from '@playwright/test'

test('Saving Buy milk once adds it once', async ({ page }) => {
  await page.goto('/')
  await page.evaluate(() => { localStorage.clear() })
  await page.reload()

  await page.getByRole("textbox", { name: "New task", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).fill("Walk dog")
  await page.getByRole("button", { name: "Save", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).fill("Buy milk")
  await page.getByRole("button", { name: "Save", exact: true }).dblclick()
  await page.waitForTimeout(700)
  await page.waitForTimeout(800)

  // Expected behaviour from the bug report
  await expect(page.getByText('Buy milk', { exact: true })).toHaveCount(1);
  await expect(page.getByText('2 tasks left', { exact: true })).toHaveCount(1);
})
